static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than 0");
        }

        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        // Assuming the year and month are valid, we calculate the day of the year
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
            daysInMonth[1] = 29; // Leap year
        }

        if (month < 1 || month > 12 || day < 1 || day > daysInMonth[month - 1]) {
            throw new IllegalArgumentException("Invalid date in timeBucket");
        }

        int dayOfYear = 0;
        for (int i = 0; i < month - 1; i++) {
            dayOfYear += daysInMonth[i];
        }
        dayOfYear += day;

        // Calculate the new day of the year based on dayStep
        int newDayOfYear = ((dayOfYear - 1) / dayStep) * dayStep + 1;

        // Convert the new day of the year back to day, month, year
        int newMonth = 0;
        int newDay = newDayOfYear;
        for (newMonth = 0; newMonth < 12; newMonth++) {
            if (newDay <= daysInMonth[newMonth]) {
                break;
            }
            newDay -= daysInMonth[newMonth];
        }

        newMonth += 1; // Convert 0-based index to 1-based month

        return year * 10000L + newMonth * 100L + newDay;
    } catch (Exception e) {
        // Handle exceptions and return a default or error value
        e.printStackTrace();
        return -1;
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than 0");
        }

        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        int offset = day % dayStep;
        if (offset != 0) {
            day -= offset;
        }

        // Handle month end edge case
        if (day <= 0) {
            if (month > 1) {
                month--;
                if (month == 2) { // February
                    if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                        day = 29; // Leap year
                    } else {
                        day = 28; // Non-leap year
                    }
                } else if (month == 4 || month == 6 || month == 9 || month == 11) {
                    day = 30; // April, June, September, November
                } else {
                    day = 31; // January, March, May, July, August, October, December
                }
            } else { // January, go to previous year
                year--;
                month = 12;
                day = 31;
            }
        }

        return year * 10000L + month * 100L + day;
    } catch (Exception e) {
        throw new RuntimeException("Error compressing time bucket", e);
    }
}

