public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must be non-negative and within the bounds of the string");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len) {
                char lowSurrogate = str.charAt(i + 1);
                if (Character.isLowSurrogate(lowSurrogate)) {
                    size += 4; // Two surrogate characters form a complete code point outside the Basic Multilingual Plane
                    i++; // Skip the low surrogate as it's already counted
                } else {
                    throw new IllegalArgumentException("High surrogate without corresponding low surrogate");
                }
            } else {
                throw new IllegalArgumentException("High surrogate at the end of the string");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

