public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    final int length = str.length();
    try {
        for (int i = 0; i < length; i++) {
            final char c = str.charAt(i);
            if (c < 0x80) {
                lb = ensureCapacity(lb, 1, session);
                lb.buffer[lb.offset++] = (byte) c;
            } else if (c < 0x800) {
                lb = ensureCapacity(lb, 2, session);
                lb.buffer[lb.offset++] = (byte) (0xc0 | (c >> 6));
                lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
            } else if (Character.isSurrogate(c)) {
                if (i + 1 >= length) {
                    throw new IllegalArgumentException("Invalid surrogate pair");
                }
                final char lowSurrogate = str.charAt(i + 1);
                if (!Character.isLowSurrogate(lowSurrogate)) {
                    throw new IllegalArgumentException("Invalid surrogate pair");
                }
                final int codePoint = Character.toCodePoint(c, lowSurrogate);
                lb = ensureCapacity(lb, 4, session);
                lb.buffer[lb.offset++] = (byte) (0xf0 | (codePoint >> 18));
                lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                lb.buffer[lb.offset++] = (byte) (0x80 | (codePoint & 0x3f));
                i++; // Skip the low surrogate
            } else {
                lb = ensureCapacity(lb, 3, session);
                lb.buffer[lb.offset++] = (byte) (0xe0 | (c >> 12));
                lb.buffer[lb.offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
                lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
            }
        }
    } catch (BufferOverflowException e) {
        throw new RuntimeException("Buffer overflow while writing UTF-8 encoded string", e);
    }
    return lb;
}

private static LinkedBuffer ensureCapacity(LinkedBuffer lb, int size, WriteSession session) {
    if (lb.offset + size > lb.limit) {
        return allocateNext(lb, size, session);
    }
