    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, skip the '(' and parse until ')'
        index = 1;
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index);
        }
        index++; // skip the ')'
    }

    // Pop the return type if it's not a void method
    if (index < descriptor.length()) {
        popType(descriptor, index);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B': case 'C': case 'D': case 'F': case 'I': case 'J': case 'S': case 'Z':
            // Single-slot types
            return index + 1;
        case 'L':
            // Object type, skip until ';'
            index = descriptor.indexOf(';', index) + 1;
            if (index == -1) {
                throw new IllegalArgumentException("Invalid descriptor: Missing ';'");
            }
            return index;
        case '[':
            // Array type, skip all '[' and then parse the component type
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            return popType(descriptor, index);
        default:
            throw new IllegalArgumentException("Invalid descriptor character: " + descriptor.charAt(index));
    }
}

