private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        // Check if the descriptor is a field descriptor
        if (descriptor.length() == 1) {
            // Handle primitive types and single-letter object types
            return; // No need to pop anything for a single character descriptor
        }

        // Check for method descriptor
        if (descriptor.startsWith("(")) {
            int endIndex = descriptor.indexOf(')');
            if (endIndex == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }

            String argumentDescriptors = descriptor.substring(1, endIndex);
            int index = 0;
            while (index < argumentDescriptors.length()) {
                char c = argumentDescriptors.charAt(index);
                switch (c) {
                    case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                        index++;
                        // Pop one slot
                        break;
                    case 'D': case 'J':
                        index++;
                        // Pop two slots
                        break;
                    case 'L': // Object type
                        int semicolonIndex = argumentDescriptors.indexOf(';', index);
                        if (semicolonIndex == -1) {
                            throw new IllegalArgumentException("Invalid method descriptor: missing ';' for object type");
                        }
                        index = semicolonIndex + 1;
                        // Pop one slot
                        break;
                    case '[': // Array type
                        index++;
                        // Continue parsing the array type
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid character in descriptor: " + c);
                }
            }
        } else {
            // Handle other cases if necessary
            throw new IllegalArgumentException("Unsupported descriptor format: " + descriptor);
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to pop types from the stack", e);
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.charAt(0) == '(') {
            // It's a method descriptor, find the argument types
            int end = descriptor.indexOf(')');
            if (end == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }
            String argTypes = descriptor.substring(1, end);
            int index = 0;
            while (index < argTypes.length()) {
                char c = argTypes.charAt(index);
                switch (c) {
                    case 'B':
                    case 'C':
                    case 'I':
                    case 'S':
                    case 'Z':
                        // These types take up one slot
                        index++;
                        break;
                    case 'D':
                    case 'J':
                        // These types take up two slots
                        index += 2;
                        break;
                    case 'F':
                        // Float takes up one slot
                        index++;
                        break;
                    case 'L':
                    case '[':
                        // Object and array types take up one slot
                        index = argTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid descriptor for object or array type");
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character in descriptor: " + c);
                }
            }
        } else {
            // It's a field descriptor, pop based on the type
            switch (descriptor.charAt(0)) {
                case 'B':
                case 'C':
                case 'I':
                case 'S':
                case 'Z':
                case 'F':
                    // These types take up one slot
                    break;
                case 'D':
                case 'J':
                    // These types take up two slots
                    break;
                case 'L':
                case '[':
                    // Object and array types take up one slot
                    if (descriptor.indexOf(';') == -1) {
                        throw new IllegalArgumentException("Invalid descriptor for object or array type: " + descriptor);
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + descriptor.charAt(0));
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

