private int removeInactiveNodes(CategoryNode node) {
    if (node == null) {
        return 0;
    }
    int count = 0;
    List<CategoryNode> activeChildren = new ArrayList<>();
    for (CategoryNode child : node.getChildren()) {
        if (child.isActive()) {
            activeChildren.add(child);
            count += removeInactiveNodes(child);
        } else {
            count++;
        }
    }
    node.setChildren(activeChildren);
    return count;
}

