public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non-null");
    }

    // Normalize the input paths
    String normalizedPath = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;
    String normalizedRelativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

    // Split the paths into segments
    String[] pathSegments = normalizedPath.split("/");
    String[] relativePathSegments = normalizedRelativePath.split("/");

    // Process the relative path segments
    for (String segment : relativePathSegments) {
        if (segment.equals("..")) {
            if (pathSegments.length > 0) {
                // Move up one directory
                pathSegments = Arrays.copyOf(pathSegments, pathSegments.length - 1);
            }
        } else if (segment.equals(".")) {
            // Stay in the current directory, do nothing
        } else {
            // Move into a subdirectory
            String[] newPathSegments = new String[pathSegments.length + 1];
            System.arraycopy(pathSegments, 0, newPathSegments, 0, pathSegments.length);
            newPathSegments[pathSegments.length] = segment;
            pathSegments = newPathSegments;
        }
    }

    // Join the path segments back into a single string
    return String.join("/", pathSegments);
}

